import{_ as t,o as d,c as o,a5 as r}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse('{"title":"Module partagé (Kotlin Multiplatform)","description":"","frontmatter":{},"headers":[],"relativePath":"applications/shared.md","filePath":"applications/shared.md","lastUpdated":1793471208000}'),c={name:"applications/shared.md"};function a(s,e,i,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="module-partage-kotlin-multiplatform" tabindex="-1">Module partagé (Kotlin Multiplatform) <a class="header-anchor" href="#module-partage-kotlin-multiplatform" aria-label="Permalink to &quot;Module partagé (Kotlin Multiplatform)&quot;">​</a></h1><p>Le cœur du système. Compilé pour la <strong>JVM</strong> (serveur, tests, Android) et en <strong>natif iOS</strong> (<code>Shared.xcframework</code>). Il porte toutes les règles métier et la base locale ; les apps ne font que l&#39;interface et le matériel.</p><table tabindex="0"><thead><tr><th>Paquet</th><th>Responsabilité</th><th>Éléments principaux</th></tr></thead><tbody><tr><td><code>money</code>, <code>checkout</code></td><td>Calcul (TVA, arrondis, remises), panier, encaissement, sessions de caisse, mouvements d&#39;espèces, ventes distantes (encaissement à table), annulations et retours, historique</td><td><code>CheckoutService</code>, <code>CashSessionManager</code>, <code>SaleCorrections</code>, <code>RemoteSales</code></td></tr><tr><td><code>catalog</code>, <code>layout</code>, <code>labels</code></td><td>Miroir local du catalogue, recherche <strong>FTS5</strong> (50 000 produits), modificateurs, boutons rapides, codes internes et planches d&#39;étiquettes</td><td><code>CatalogSyncRepository</code>, <code>FtsQuery</code>, <code>SalesLayout</code>, <code>LabelSheet</code></td></tr><tr><td><code>inventory</code></td><td>Mouvements de stock signés, stock = somme des mouvements, inventaires et pertes</td><td><code>StockSyncRepository</code>, <code>InventoryRepository</code></td></tr><tr><td><code>customers</code></td><td>Clients, fidélité, ardoise, reçus digitaux</td><td><code>CustomerRepository</code>, <code>LoyaltyRepository</code>, <code>CreditRepository</code></td></tr><tr><td><code>purchasing</code></td><td>Bons de commande reçus, réception mobile</td><td><code>PurchaseOrderRepository</code>, <code>ReceptionService</code></td></tr><tr><td><code>reports</code></td><td>Anti-fraude (retraits de lignes), alertes des responsables</td><td><code>ManagerAlertRepository</code></td></tr><tr><td><code>platform</code></td><td>Compte Vendora : droits de la formule et statut de l&#39;abonnement (bannière, jamais de blocage de la vente)</td><td><code>TenantAccountRepository</code></td></tr><tr><td><code>auth</code></td><td>Sessions utilisateur par PIN, verrou, inactivité, approbations manager hors ligne, cache d&#39;auth chiffré</td><td><code>UserSession</code>, <code>ManagerApproval</code>, <code>PinCacheVault</code></td></tr><tr><td><code>fiscal</code></td><td>Scellement chaîné des ventes, clôtures J/M/A, mode formation</td><td><code>FiscalSeal</code>, <code>FiscalClosure</code>, <code>TrainingMode</code></td></tr><tr><td><code>restaurant</code></td><td>Plan de salle, additions, opérations (transfert, fusion, partage, offert), encaissement d&#39;addition, postes de préparation, bons cuisine, KDS</td><td><code>Orders</code>, <code>OrderOperations</code>, <code>OrderCheckout</code>, <code>KitchenTicketService</code>, <code>Kds</code></td></tr><tr><td><code>printing</code>, <code>hardware</code></td><td>Rendu ESC/POS, file d&#39;impression persistante avec reprise, états d&#39;imprimante, imprimante simulée, diagnostic matériel</td><td><code>EscPosRenderer</code>, <code>PrintQueueWorker</code>, <code>SimulatedPrinter</code></td></tr><tr><td><code>payments</code></td><td>Intents de paiement fournisseur côté appareil</td><td><code>PaymentIntentClient</code></td></tr><tr><td><code>theme</code>, <code>i18n</code></td><td>Tokens de design, thème magasin / marque, logo, configuration par appareil, presets kiosque, traductions fr / en / ar + RTL</td><td><code>DesignTokens</code>, <code>StoreTheme</code>, <code>DeviceConfig</code>, <code>AppStrings</code></td></tr><tr><td><code>sync</code></td><td>Enveloppe d&#39;événement, outbox, client push / pull, rattrapage, version d&#39;app</td><td><code>SyncClient</code>, <code>OutboxRepository</code>, <code>AppVersion</code></td></tr><tr><td><code>hub</code></td><td>Nœud du hub local : découverte, élection, relais TCP, rattrapage, clé LAN, identité Ed25519, annuaire des pairs</td><td><code>HubNode</code>, <code>HubProtocol</code>, <code>LanKey</code>, <code>LanPeer</code></td></tr><tr><td><code>crypto</code></td><td>SHA-256, PBKDF2, HMAC, interfaces Ed25519 (JDK / BouncyCastle / CryptoKit fournis par la plateforme)</td><td><code>Pbkdf2</code>, <code>DeviceKeys</code></td></tr><tr><td><code>perf</code></td><td>Mesure de latence par action caissier, télémétrie, catalogue de référence 50 000 produits</td><td><code>ActionLatencyRecorder</code>, <code>LatencyTelemetry</code></td></tr><tr><td><code>db</code></td><td>Schéma SQLDelight et migrations (<code>.sq</code>, <code>.sqm</code>)</td><td><a href="/VendoraSystem-docs/reference/migrations">Données et migrations</a></td></tr></tbody></table><p>Tests : les scénarios du module partagé tournent <strong>deux fois</strong> (JVM et simulateur iOS). Voir <a href="/VendoraSystem-docs/tests/scenarios">scénarios</a>.</p>',4)])])}const h=t(c,[["render",a]]);export{m as __pageData,h as default};
